<script lang="ts">
  import { onMount } from 'svelte'
  import { api } from '$lib/api'
  let rows: any[] = []; let error = ''; let search = ''; let pageNumber = 1; let pages = 1; let total = 0; let loading = false
  async function load() { loading = true; error = ''; try { const result = await api<{ data: any[]; pagination: { pages: number; total: number } }>(`/admin/users?page=${pageNumber}&limit=20&q=${encodeURIComponent(search)}`); rows = result.data; pages = Math.max(1, result.pagination.pages); total = result.pagination.total } catch (reason: any) { error = reason.message } finally { loading = false } }
  onMount(() => { void load() })
  async function toggle(user: any) { const status = user.status === 'active' ? 'suspended' : 'active'; try { await api(`/admin/users/${user._id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); await load() } catch (reason: any) { error = reason.message } }
</script>
<main class="admin-content"><div class="page-title"><div><span class="kicker">ACCESS CONTROL</span><h1>Users</h1><p>Review accounts and manage access status.</p></div><span class="count-pill">{total} total</span></div>{#if error}<div class="notice error">{error}</div>{/if}<div class="toolbar"><input aria-label="Search name or email" placeholder="Search name or email" bind:value={search} onkeydown={(event) => { if (event.key === 'Enter') { pageNumber = 1; void load() } }} /><button class="secondary-button" onclick={() => { pageNumber = 1; void load() }}>Search</button></div><section class="panel table-panel"><table><thead><tr><th>Account</th><th>Role</th><th>Status</th><th>Last sign in</th><th></th></tr></thead><tbody>{#each rows as user}<tr><td><b>{user.name}</b><small>{user.email}</small></td><td><span class="role-pill">{user.role}</span></td><td><span class:green={user.status === 'active'} class="status-pill">{user.status}</span></td><td>{user.lastLoginAt ? new Date(user.lastLoginAt).toLocaleDateString() : 'Never'}</td><td>{#if user.role !== 'admin'}<button class="text-action" onclick={() => toggle(user)}>{user.status === 'active' ? 'Suspend' : 'Restore'}</button>{/if}</td></tr>{/each}</tbody></table>{#if !rows.length}<p class="table-empty">{loading ? 'Loading accounts…' : 'No accounts found.'}</p>{/if}</section><div class="admin-pagination"><span>Page {pageNumber} of {pages}</span><div><button class="secondary-button" disabled={pageNumber <= 1 || loading} onclick={() => { pageNumber -= 1; void load() }}>Previous</button><button class="secondary-button" disabled={pageNumber >= pages || loading} onclick={() => { pageNumber += 1; void load() }}>Next</button></div></div></main>
